101	  test('adding a new invoice for an amount shows it and grows the total', async ({ page }) => {
102	    await resetAndSeed({
103	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
104	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
105	      invoices: [{ id: 1, amount: 100, projectId: 1 }],
106	    });
107	
108	    await page.goto('/projects/1');
