123	
124	    // Both invoices are now listed, and the total has grown to 100 + 300 = 400.
125	    await expect(invoiceRows(page)).toHaveCount(2);
126	    await expectAmount(page.getByTestId('project-invoices-total'), 400);
127	
128	    // And it survives a fresh load from the server.
129	    await page.reload();
130	    await expect(invoiceRows(page)).toHaveCount(2);
131	    await expect(
132	      invoiceRows(page).filter({
133	        has: page.getByTestId('invoice-amount').getByText('300', { exact: false }),
134	      }),
135	    ).toHaveCount(1);
136	    await expectAmount(page.getByTestId('project-invoices-total'), 400);
137	  });
138	
139	  test('a new invoice added to an empty project appears and the total reflects it', async ({
140	    page,
141	  }) => {
142	    await resetAndSeed({
143	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
144	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
145	      invoices: [],
146	    });
147	
148	    await page.goto('/projects/1');
149	    await expect(invoiceRows(page)).toHaveCount(0);
150	    await expectAmount(page.getByTestId('project-invoices-total'), 0);
151	
152	    await page.getByTestId('invoice-form-amount').fill('175');
153	    await page.getByTestId('invoice-form-submit').click();
154	
155	    await expect(invoiceRows(page)).toHaveCount(1);
156	    await expectAmount(invoiceRows(page).getByTestId('invoice-amount'), 175);
157	    await expectAmount(page.getByTestId('project-invoices-total'), 175);
158	  });
159	});
