1	import { InvoiceListToolbar } from '../../slots/defs/invoiceListToolbar';
2	import { useSearchParam, asString } from '../../url/useSearchParam';
3	import { formatMoney } from '../../ui/money';
4	import { useInvoices, usePayInvoice, useSendInvoice } from './invoices';
5	
6	// A project's invoices and what they add up to. Reads its own query key (scoped to the project) and
7	// derives the total from the rows — the aggregate is never stored, so it always matches the list.
8	// Each row shows its lifecycle status and the control for its next step: Send while DRAFT, Mark paid
9	// while SENT (payment is only offered once an invoice has been sent), nothing once PAID. The ordering comes
10	// from the shared `invoiceSort` URL key (set by a toolbar control), so the server returns the rows
